import '../models/router_config.dart';import 'routeros_rest_api.dart';import 'routeros_binary_api.dart';
class MikrotikService {RouterOsRestApi? _api;Future<bool> connect(RouterConfigModel c) async {if(c.version=='v6')return RouterOsBinaryApi().testPort(c.host,c.port);_api=RouterOsRestApi('${c.ssl?'https':'http'}://${c.host}:${c.port}',c.username,c.password);await _api!.resource();return true;}Future<Map<String,dynamic>> resource()=>_api?.resource()??Future.error(Exception('اتصل براوتر RouterOS v7 أولاً'));Future<List<dynamic>> hotspot()=>_api?.hotspotUsers()??Future.error(Exception('اتصل براوتر RouterOS v7 أولاً'));Future<List<dynamic>> ppp()=>_api?.pppUsers()??Future.error(Exception('اتصل براوتر RouterOS v7 أولاً'));}
